function M(n,r="en"){if(!n)return"—";try{const t=new Date(n);return Number.isNaN(t.getTime())?"—":t.toLocaleDateString(r||"en",{month:"short",day:"numeric",year:"numeric"})}catch{return"—"}}function m(n,r="—"){if(n==null||n==="")return r;try{const t=new Date(n);if(isNaN(t.getTime())||t.getFullYear()<1970)return r;const a=new Date,o=a-t,e=Math.floor(o/6e4),u=Math.floor(o/36e5),s=Math.floor(o/864e5);if(e<1)return"Just now";if(e<60)return`${e} ${e===1?"minute":"minutes"} ago`;if(u<24)return`${u} ${u===1?"hour":"hours"} ago`;if(s<7)return`${s} ${s===1?"day":"days"} ago`;const i=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][t.getMonth()],f=t.getDate(),c=t.getFullYear();return c===a.getFullYear()?`${i} ${f}`:`${i} ${f}, ${c}`}catch{return r}}function y(n,r="—"){if(n==null||n==="")return r;try{const t=new Date(n);if(isNaN(t.getTime()))return r;const a=new Date;if(t<a)return m(n,r);const o=t-a,e=Math.floor(o/6e4),u=Math.floor(o/36e5),s=Math.floor(o/864e5);return e<60?`in ${e} ${e===1?"minute":"minutes"}`:u<24?`in ${u} ${u===1?"hour":"hours"}`:s<7?`in ${s} ${s===1?"day":"days"}`:`${["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][t.getMonth()]} ${t.getDate()}`}catch{return r}}export{y as a,M as b,m as f};
